"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route table before reading a body."""

    # Look up the route using the same path spelling the rest of the service uses.
    return canonical_path(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

"""Storage-independent audit log service.

``AuditLogService`` depends only on the :class:`EventStore` and
:class:`~auditlog.index_segments.QueryIndex` contracts, never on a concrete
backing store or index implementation. Either half is freely replaceable:
swap the store for a different persistence mechanism, or swap the index for a
different rebuild or query strategy, without changing the other or the
service itself. Everything here is the Python standard library only.
"""

from __future__ import annotations

from collections.abc import Iterator
from typing import Protocol

from .index_segments import QueryIndex
from .models import AuditEvent, RebuildPlan


class EventStore(Protocol):
    """Storage-independent contract for the append-only source of events."""

    def append(self, event: AuditEvent) -> None: ...

    def iter_events(self) -> Iterator[AuditEvent]: ...


class InMemoryEventStore:
    """Reference :class:`EventStore`: an append-only, order-preserving list.

    Existing entries are never replaced or reordered; ``append`` only grows
    the trail.
    """

    def __init__(self) -> None:
        self._events: list[AuditEvent] = []

    def append(self, event: AuditEvent) -> None:
        self._events.append(event)

    def iter_events(self) -> Iterator[AuditEvent]:
        return iter(self._events)


class AuditLogService:
    """Wires a source-of-truth event store to a replaceable query index.

    ``repair`` rebuilds the index by reading the store; it never writes back
    to the store, so the source events it reads stay exactly as recorded.
    """

    def __init__(self, store: EventStore, index: QueryIndex) -> None:
        self._store = store
        self._index = index

    def record(self, event: AuditEvent) -> None:
        self._store.append(event)

    def query(
        self, *, actor: str | None = None, action: str | None = None, outcome: str | None = None
    ) -> list[AuditEvent]:
        return self._index.query(actor=actor, action=action, outcome=outcome)

    def repair(self) -> RebuildPlan:
        """Rebuild the query index from the store's immutable source events."""

        return self._index.rebuild(self._store.iter_events())

"""A replaceable query index built from immutable source events.

The index is organized as content-addressed segments (see
``auditlog.models.IndexSegment``). Rebuilding only ever reads the source
events it is given and returns new segment and plan objects: it never writes
back to, mutates, or reorders the events themselves.
"""

from __future__ import annotations

from collections.abc import Iterable
from typing import Protocol

from .models import AuditEvent, IndexSegment, RebuildPlan, plan_identity, segment_identity

DEFAULT_SEGMENT_SIZE = 100


class QueryIndex(Protocol):
    """Storage-independent contract for a query index over the event log.

    A service depends only on this surface, never on how a particular index
    organizes or stores its segments, so one implementation can be swapped
    for another without touching the service or the event store.
    """

    def query(
        self, *, actor: str | None = None, action: str | None = None, outcome: str | None = None
    ) -> list[AuditEvent]: ...

    def rebuild(self, events: Iterable[AuditEvent]) -> RebuildPlan: ...


def build_segments(
    events: Iterable[AuditEvent], *, segment_size: int = DEFAULT_SEGMENT_SIZE
) -> tuple[IndexSegment, ...]:
    """Partition source events, in their append order, into content-addressed segments.

    A segment's id is derived only from the content ids of the events it
    covers, so its ``checkpoint_sequence`` — the last source sequence it
    happens to reach — never changes that id: two rebuilds that cover the
    same events converge on the same segment regardless of when either ran.
    """

    if segment_size < 1:
        raise ValueError("segment_size must be >= 1")

    ordered = list(events)
    segments: list[IndexSegment] = []
    for start in range(0, len(ordered), segment_size):
        chunk = ordered[start : start + segment_size]
        content_ids = tuple(event.event_id for event in chunk)
        segments.append(
            IndexSegment(
                segment_id=segment_identity(content_ids),
                content_ids=content_ids,
                checkpoint_sequence=chunk[-1].sequence,
            )
        )
    return tuple(segments)


def build_rebuild_plan(
    events: Iterable[AuditEvent], *, segment_size: int = DEFAULT_SEGMENT_SIZE
) -> RebuildPlan:
    """Derive the full rebuild plan for a set of source events.

    Reads ``events`` and returns new segment and plan objects; the source
    events themselves are never rewritten or reordered.
    """

    ordered = list(events)
    segments = build_segments(ordered, segment_size=segment_size)
    checkpoint_sequence = ordered[-1].sequence if ordered else 0
    return RebuildPlan(
        plan_id=plan_identity(tuple(segment.segment_id for segment in segments)),
        segments=segments,
        checkpoint_sequence=checkpoint_sequence,
    )


class SegmentedQueryIndex:
    """Reference, in-memory implementation of :class:`QueryIndex`.

    Holds only what a rebuild derives from the source events: the segments
    and a lookup from content id to event. ``rebuild`` always re-derives this
    from the events it is passed, so the store — not the index — remains the
    source of truth.
    """

    def __init__(self) -> None:
        self._segments: tuple[IndexSegment, ...] = ()
        self._events_by_content_id: dict[str, AuditEvent] = {}

    @property
    def segments(self) -> tuple[IndexSegment, ...]:
        return self._segments

    def rebuild(self, events: Iterable[AuditEvent]) -> RebuildPlan:
        ordered = list(events)
        plan = build_rebuild_plan(ordered)
        self._segments = plan.segments
        self._events_by_content_id = {event.event_id: event for event in ordered}
        return plan

    def query(
        self, *, actor: str | None = None, action: str | None = None, outcome: str | None = None
    ) -> list[AuditEvent]:
        matches: list[AuditEvent] = []
        for segment in self._segments:
            for content_id in segment.content_ids:
                event = self._events_by_content_id.get(content_id)
                if event is None:
                    continue
                if actor is not None and event.actor != actor:
                    continue
                if action is not None and event.action != action:
                    continue
                if outcome is not None and event.outcome != outcome:
                    continue
                matches.append(event)
        return matches

"""Stable complete-identity helpers for compatibility repair."""

from __future__ import annotations


def complete_event_identity(recorded_at: str, content_id: str) -> str:
    """Return complete immutable event identity."""

    return "\x1f".join((recorded_at, content_id))


def durable_repair_key(actor: str, action: str, outcome: str, recorded_at: str, content_id: str) -> str:
    """Persist complete event identity for later repair."""

    return complete_event_identity(recorded_at, content_id)


def repair_group_key(stored_repair_key: str | None, recorded_at: str, content_id: str) -> str:
    """Recompute complete identity before compatibility grouping."""

    complete = complete_event_identity(recorded_at, content_id)
    if stored_repair_key == complete:
        return stored_repair_key
    return complete

