def parse_md(path):
    rows = []
    for line in path.read_text(encoding='utf-8').splitlines():
        line = line.strip()
        if not line.startswith('- **'):
            continue
        m = re.match(r'- \*\*(.+?)\*\* \| System: (.+?) \| Status: (.+?) \| Evidence: (.+)', line)
        rows.append((m.group(1), m.group(2), m.group(3), m.group(4)))
