cd "C:\Users\Billy\AppData\Local\Temp\lcm-live-2p2gih8h\audit-route-s04" && python -c "
import json, re, pathlib

d = pathlib.Path('maintenance/inputs/s04-corruption-cases')

def parse_md(path):
    rows = []
    for line in path.read_text(encoding='utf-8').splitlines():
        line = line.strip()
        if not line.startswith('- **'):
            continue
        m = re.match(r'- \*\*(.+?)\*\* \| System: (.+?) \| Status: (.+?) \| Evidence: (.+)', line)
        rows.append((m.group(1), m.group(2), m.group(3), m.group(4)))
    return rows

def parse_jsonl(path):
    rows = []
    for line in path.read_text(encoding='utf-8').splitlines():
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        rows.append((o['case'], o['system'], o['status'], o['note']))
    return rows

def parse_csv(path):
    import csv
    rows = []
    with path.open(encoding='utf-8', newline='') as f:
        r = csv.reader(f)
        header = next(r)
        for row in r:
            rows.append(tuple(row))
    return rows

def parse_yaml(path):
    rows = []
    case = system = status = note = None
    for line in path.read_text(encoding='utf-8').splitlines():
        line = line.rstrip()
        if line.startswith('- case:'):
            if case is not None:
                rows.append((case, system, status, note))
            case = line.split('- case:',1)[1].strip()
        elif line.strip().startswith('system:'):
            system = line.split('system:',1)[1].strip()
        elif line.strip().startswith('status:'):
            status = line.split('status:',1)[1].strip()
        elif line.strip().startswith('note:'):
            note = line.split('note:',1)[1].strip().strip('\"')
    if case is not None:
        rows.append((case, system, status, note))
    return rows

