jsonl = parse_jsonl(d / 'audit-route-s04-t08-evidence-02.jsonl')
csvr = parse_csv(d / 'audit-route-s04-t08-evidence-03.csv')
yaml = parse_yaml(d / 'audit-route-s04-t08-evidence-04.yaml')

print('md records:', len(md), md[0], md[-1])
print('jsonl records:', len(jsonl), jsonl[0], jsonl[-1])
print('csv records:', len(csvr), csvr[0], csvr[-1])
print('yaml records:', len(yaml), yaml[0], yaml[-1])

overlap = min(len(md), len(jsonl), len(csvr), len(yaml))
print('overlap range: 1..' + str(overlap))

diffs = []
for i in range(overlap):
    vals = {'md': md[i], 'jsonl': jsonl[i], 'csv': csvr[i], 'yaml': yaml[i]}
    base = md[i]
    for name, v in vals.items():
        if v != base:
            diffs.append((i+1, name, v, base))

print('diff count in overlap:', len(diffs))
for x in diffs[:20]:
    print(x)
