cd "C:\Users\Billy\AppData\Local\Temp\lcm-live-2p2gih8h\audit-route-s04" && python -c "
import json, csv, re

base = 'maintenance/inputs/s04-search-parity/'

# Parse md
md_records = {}
with open(base+'audit-route-s04-t10-evidence-01.md', encoding='utf-8') as f:
    for line in f:
        line = line.rstrip('\r\n')
        m = re.match(r'- \*\*(?P<case>[\w-]+)\*\* \| System: (?P<system>[\w-]+) \| Status: (?P<status>[\w-]+) \| Evidence: (?P<note>.+)$', line)
        if m:
            md_records[m.group('case')] = (m.group('system'), m.group('status'), m.group('note'))
print('md count:', len(md_records))

# Parse jsonl
jsonl_records = {}
with open(base+'audit-route-s04-t10-evidence-02.jsonl', encoding='utf-8') as f:
    for line in f:
        line = line.strip()
        if not line: continue
        d = json.loads(line)
        jsonl_records[d['case']] = (d['system'], d['status'], d['note'])
print('jsonl count:', len(jsonl_records))

# Parse csv
csv_records = {}
with open(base+'audit-route-s04-t10-evidence-03.csv', encoding='utf-8', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_records[row['case']] = (row['system'], row['status'], row['note'])
print('csv count:', len(csv_records))

# Parse yaml (hand-rolled, since it's a simple fixed-structure list)
yaml_records = {}
with open(base+'audit-route-s04-t10-evidence-04.yaml', encoding='utf-8') as f:
    lines = [l.rstrip('\r\n') for l in f]
i = 1  # skip title line
cur = {}
while i < len(lines):
    line = lines[i]
    if line.startswith('- case:'):
        if cur:
            yaml_records[cur['case']] = (cur['system'], cur['status'], cur['note'])
        cur = {'case': line.split('- case:')[1].strip()}
    elif line.strip().startswith('system:'):
        cur['system'] = line.split('system:')[1].strip()
    elif line.strip().startswith('status:'):
        cur['status'] = line.split('status:')[1].strip()
    elif line.strip().startswith('note:'):
        cur['note'] = line.split('note:',1)[1].strip().strip('\"')
    i += 1
if cur:
    yaml_records[cur['case']] = (cur['system'], cur['status'], cur['note'])
print('yaml count:', len(yaml_records))

# Case number ranges
def case_num(c):
    return int(c.split('-')[-1])

for name, recs in [('md', md_records), ('jsonl', jsonl_records), ('csv', csv_records), ('yaml', yaml_records)]:
    nums = sorted(case_num(c) for c in recs)
    print(name, 'min', nums[0], 'max', nums[-1], 'contiguous:', nums == list(range(nums[0], nums[-1]+1)))

# Shared range comparison
shared_max = min(max(case_num(c) for c in recs) for recs in [md_records, jsonl_records, csv_records, yaml_records])
print('shared_max:', shared_max)

diffs = []
for n in range(1, shared_max+1):
    case = f'audit-route-s04-t10-{n:06d}'
    vals = {
        'md': md_records.get(case),
        'jsonl': jsonl_records.get(case),
        'csv': csv_records.get(case),
        'yaml': yaml_records.get(case),
    }
    uniq = set(vals.values())
    if len(uniq) > 1:
        diffs.append((case, vals))

print('field-level diffs across shared range:', len(diffs))
for d in diffs[:10]:
    print(d)

# status/system cycle check
cycle_map = {}
for n in range(1, shared_max+1):
    case = f'audit-route-s04-t10-{n:06d}'
    system, status, note = md_records[case]
    mod = n % 4
    cycle_map.setdefault(mod, set()).add((system, status))
for mod, s in sorted(cycle_map.items()):
    print('mod', mod, '->', s)
"

