cd "C:\Users\Billy\AppData\Local\Temp\lcm-live-2p2gih8h\audit-route-s04\maintenance\inputs\s04-operator-cases" && python - <<'EOF'
import json, re, csv, io

# parse md
md_cases = {}
with open("audit-route-s04-t13-evidence-01.md", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line.startswith("- **"):
            continue
        m = re.match(r"- \*\*(?P<case>[\w-]+)\*\* \| System: (?P<system>[\w-]+) \| Status: (?P<status>[\w-]+) \| Evidence: (?P<note>.+)$", line)
        if not m:
            print("MD PARSE FAIL:", line)
            continue
        d = m.groupdict()
        md_cases[d["case"]] = (d["system"], d["status"], d["note"])

# parse jsonl
jsonl_cases = {}
with open("audit-route-s04-t13-evidence-02.jsonl", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        jsonl_cases[obj["case"]] = (obj["system"], obj["status"], obj["note"])

# parse csv
csv_cases = {}
with open("audit-route-s04-t13-evidence-03.csv", encoding="utf-8", newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_cases[row["case"]] = (row["system"], row["status"], row["note"])

# parse yaml (manual, simple structure)
yaml_cases = {}
with open("audit-route-s04-t13-evidence-04.yaml", encoding="utf-8") as f:
    lines = [l.rstrip("\n").rstrip("\r") for l in f]
cur = {}
case_id = None
for line in lines[1:]:
    line_stripped = line.strip()
    if line_stripped.startswith("- case:"):
        if case_id:
            yaml_cases[case_id] = (cur.get("system"), cur.get("status"), cur.get("note"))
        case_id = line_stripped.split(":", 1)[1].strip()
        cur = {}
    elif line_stripped.startswith("system:"):
        cur["system"] = line_stripped.split(":", 1)[1].strip()
    elif line_stripped.startswith("status:"):
        cur["status"] = line_stripped.split(":", 1)[1].strip()
    elif line_stripped.startswith("note:"):
        note_val = line_stripped.split(":", 1)[1].strip()
        if note_val.startswith('"') and note_val.endswith('"'):
            note_val = note_val[1:-1]
        cur["note"] = note_val
if case_id:
    yaml_cases[case_id] = (cur.get("system"), cur.get("status"), cur.get("note"))

print("counts:", len(md_cases), len(jsonl_cases), len(csv_cases), len(yaml_cases))
print("md range:", sorted(md_cases)[0], sorted(md_cases)[-1])
print("jsonl range:", sorted(jsonl_cases)[0], sorted(jsonl_cases)[-1])
print("csv range:", sorted(csv_cases)[0], sorted(csv_cases)[-1])
print("yaml range:", sorted(yaml_cases)[0], sorted(yaml_cases)[-1])

shared = sorted(set(md_cases) & set(jsonl_cases) & set(csv_cases) & set(yaml_cases))
print("shared count:", len(shared))

diffs = []
for c in shared:
    vals = {"md": md_cases[c], "jsonl": jsonl_cases[c], "csv": csv_cases[c], "yaml": yaml_cases[c]}
    if len(set(vals.values())) > 1:
        diffs.append((c, vals))

print("field-level diffs across shared range:", len(diffs))
for d in diffs[:10]:
    print(d)
EOF

