yaml_cases = {}
with open("audit-route-s04-t14-evidence-04.yaml", encoding="utf-8") as f:
    lines = [l.rstrip("\n").rstrip("\r") for l in f]
cur = {}
case_id = None
for line in lines[1:]:
    ls = line.strip()
    if ls.startswith("- case:"):
        if case_id:
            yaml_cases[case_id] = (cur.get("system"), cur.get("status"), cur.get("note"))
        case_id = ls.split(":", 1)[1].strip()
        cur = {}
    elif ls.startswith("system:"):
        cur["system"] = ls.split(":", 1)[1].strip()
    elif ls.startswith("status:"):
        cur["status"] = ls.split(":", 1)[1].strip()
    elif ls.startswith("note:"):
        v = ls.split(":", 1)[1].strip()
        if v.startswith('"') and v.endswith('"'):
            v = v[1:-1]
        cur["note"] = v
if case_id:
    yaml_cases[case_id] = (cur.get("system"), cur.get("status"), cur.get("note"))

print("counts:", len(md_cases), len(jsonl_cases), len(csv_cases), len(yaml_cases))
print("md range:", sorted(md_cases)[0], sorted(md_cases)[-1])
print("jsonl range:", sorted(jsonl_cases)[0], sorted(jsonl_cases)[-1])
print("csv range:", sorted(csv_cases)[0], sorted(csv_cases)[-1])
print("yaml range:", sorted(yaml_cases)[0], sorted(yaml_cases)[-1])

shared = sorted(set(md_cases) & set(jsonl_cases) & set(csv_cases) & set(yaml_cases))
print("shared count:", len(shared))

diffs = []
